begin;
select no_plan();
create function pg_temp.ai_id(n integer) returns uuid language sql immutable as $$select ('ad030000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.ai_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','ai-transition-'||n||'@test.invalid' from generate_series(1,5) n;
insert into public.profiles(id,role,name) select pg_temp.ai_id(n),case n when 1 then 'admin' when 2 then 'staff' when 3 then 'teacher' when 4 then 'assistant' else 'staff' end,'synthetic transition' from generate_series(1,5) n on conflict(id) do update set role=excluded.role;
insert into dashboard_private.ai_agent_requests(id,requester_id,title,body) values(pg_temp.ai_id(10),pg_temp.ai_id(2),'synthetic','synthetic');
insert into dashboard_private.ai_agent_credentials(id,created_by,label,token_hash,scopes,expires_at) values(pg_temp.ai_id(20),pg_temp.ai_id(1),'synthetic',repeat('d',64),array['ai-agent:requests:read','ai-agent:requests:claim','ai-agent:requests:update'],now()+interval '1 day');
insert into dashboard_private.ai_agent_credential_grants(credential_id,queues,actions,expires_at) values(pg_temp.ai_id(20),array['employee_requests'],array['read','claim','renew','progress','question','done'],now()+interval '1 day');
set local role service_role;
select lives_ok($q$select public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(10),'version','1','idempotencyKey',pg_temp.ai_id(30),'claimTokenHash',repeat('a',64)))$q$,'pending claim is a transactional writer');
reset role;
select is((select status from dashboard_private.ai_agent_requests where id=pg_temp.ai_id(10)),'processing','claim atomically advances status');
select is((select count(*) from dashboard_private.ai_agent_request_events where request_id=pg_temp.ai_id(10) and kind='claimed'),1::bigint,'one immutable claim event');
create temp table ev(k text primary key,v jsonb);
grant all on ev to authenticated,service_role;
insert into ev select 'claimed_snapshot',dashboard_private.ai_agent_request_json_v1(r) from dashboard_private.ai_agent_requests r where id=pg_temp.ai_id(10);
create function pg_temp.bot(op text,rid integer,ver text,kid integer,extra jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_bot_api_v1(repeat('d',64),op,jsonb_build_object('id',pg_temp.ai_id(rid),'version',ver,'idempotencyKey',pg_temp.ai_id(kid),'claimTokenHash',repeat('a',64),'claimGeneration','1')||extra)$$;
create function pg_temp.user_op(op text,rid integer,ver text,kid integer,extra jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_user_api_v1(op,jsonb_build_object('id',pg_temp.ai_id(rid),'version',ver,'idempotencyKey',pg_temp.ai_id(kid))||extra)$$;
-- Lost claim response is replayable only while exactly that claim is live.
set local role service_role;
select is(public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(10),'version','1','idempotencyKey',pg_temp.ai_id(30),'claimTokenHash',repeat('a',64)))->'claim'->>'generation','1','live claim replay returns decimal generation');
select throws_ok($q$select public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(10),'version','1','idempotencyKey',pg_temp.ai_id(30),'claimTokenHash',repeat('b',64)))$q$,'23514','ai_agent_idempotency_conflict','changed claim body has exact idempotency SQLSTATE');
select throws_ok($q$select public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(10),'version','2','idempotencyKey',pg_temp.ai_id(31),'claimTokenHash',repeat('b',64)))$q$,'55000','ai_agent_conflict','a second claimer has domain conflict 55000');
insert into ev values('renew',pg_temp.bot('renew',10,'2',32));
select is((select v->'request'->>'version' from ev where k='renew'),'2','renew keeps business version');
select is((select v->'request'->>'updatedAt' from ev where k='renew'),(select v->>'updatedAt' from ev where k='claimed_snapshot'),'renew preserves business updatedAt too');
insert into ev values('progress',pg_temp.bot('progress',10,'2',33,'{"text":"read-only investigation"}'));
select is((select v->'request'->>'version' from ev where k='progress'),'3','progress appends and advances business version');
select throws_ok($q$select pg_temp.bot('progress',10,'2',34,'{"text":"stale"}')$q$,'55000','ai_agent_stale_version','stale version conflict exact 55000');
select throws_ok($q$select pg_temp.bot('progress',10,'3',35,jsonb_build_object('text','wrong claim','claimTokenHash',repeat('b',64)))$q$,'55000','ai_agent_claim_lost','wrong claim hash denied');
insert into ev values('question',pg_temp.bot('question',10,'3',36,'{"text":"Which item?"}'));
select is(pg_temp.bot('question',10,'3',36,'{"text":"Which item?"}'),(select v from ev where k='question'),'lost question response has narrow ended-generation receipt replay');
reset role;
select is((select status from dashboard_private.ai_agent_requests where id=pg_temp.ai_id(10)),'question','question transition committed');
select is((select count(*) from dashboard_private.ai_agent_request_claims where request_id=pg_temp.ai_id(10)),0::bigint,'question ends claim');
select set_config('request.jwt.claim.sub',pg_temp.ai_id(2)::text,true);
set local role authenticated;
insert into ev values('answer',pg_temp.user_op('append_message',10,'4',37,jsonb_build_object('kind','answer','text','Fixture item','questionId',(select v->'message'->>'id' from ev where k='question'))));
select is((select v->'request'->>'status' from ev where k='answer'),'pending','answer atomically makes pending');
select is((select v->'request'->>'openQuestionId' from ev where k='answer'),null,'answer closes open question in same commit');
select is((select v->'message'->>'seq' from ev where k='answer'),'3','audit message seq is bounded decimal string');
select is(pg_temp.user_op('append_message',10,'4',37,jsonb_build_object('kind','answer','text','Fixture item','questionId',(select v->'message'->>'id' from ev where k='question'))),(select v from ev where k='answer'),'answer replay returns original outcome without extra effect');
select throws_ok($q$select pg_temp.user_op('append_message',10,'5',38,jsonb_build_object('kind','answer','text','closed','questionId',(select v->'message'->>'id' from ev where k='question')))$q$,'55000','ai_agent_question_conflict','closed question has exact final-function domain code');
select throws_ok($q$select pg_temp.user_op('append_message',10,'4',37,jsonb_build_object('kind','answer','text','changed','questionId',(select v->'message'->>'id' from ev where k='question')))$q$,'23514','ai_agent_idempotency_conflict','changed answer replay denied');
reset role;
select is((select count(*) from dashboard_private.ai_agent_request_messages where request_id=pg_temp.ai_id(10) and kind='answer'),1::bigint,'replay added zero answers');
set local role service_role;
select is(public.ai_agent_bot_api_v1(repeat('d',64),'list','{}')->'items'->0->>'id',pg_temp.ai_id(10)::text,'answer is found on fresh ready_at first page regardless of created_at');
select throws_ok($q$select public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(10),'version','1','idempotencyKey',pg_temp.ai_id(30),'claimTokenHash',repeat('a',64)))$q$,'55000','ai_agent_claim_lost','old claim replay after generation ended rejected');
select throws_ok($q$select pg_temp.bot('question',10,'3',36,'{"text":"Which item?"}')$q$,'55000','ai_agent_claim_lost','answer invalidates old question readback receipt');
reset role;
-- Every employee role uses the actual append/cancel writer for own requests.
insert into dashboard_private.ai_agent_requests(id,requester_id,title,body) select pg_temp.ai_id(n),pg_temp.ai_id(case n when 11 then 2 when 12 then 3 when 13 then 5 when 14 then 2 when 15 then 3 else 5 end),'synthetic own','synthetic' from generate_series(11,16)n;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(2)::text,true);
set local role authenticated;
select is(pg_temp.user_op('append_message',11,'1',41,'{"kind":"comment","text":"staff"}')->'request'->>'version','2','staff own append works');
select is(pg_temp.user_op('cancel',14,'1',42)->>'status','cancelled','staff own cancel works');
select throws_ok($q$select pg_temp.user_op('append_message',12,'1',43,'{"kind":"comment","text":"other"}')$q$,'P0002','ai_agent_not_found','staff other append denied');
select throws_ok($q$select pg_temp.user_op('cancel',15,'1',44)$q$,'P0002','ai_agent_not_found','staff other cancel denied');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(3)::text,true);
set local role authenticated;
select is(pg_temp.user_op('append_message',12,'1',45,'{"kind":"comment","text":"teacher"}')->'request'->>'version','2','teacher own append works');
select is(pg_temp.user_op('cancel',15,'1',46)->>'status','cancelled','teacher own cancel works');
select throws_ok($q$select pg_temp.user_op('append_message',13,'1',47,'{"kind":"comment","text":"other"}')$q$,'P0002','ai_agent_not_found','teacher other append denied');
select throws_ok($q$select pg_temp.user_op('cancel',16,'1',48)$q$,'P0002','ai_agent_not_found','teacher other cancel denied');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(4)::text,true);
set local role authenticated;
select throws_ok($q$select pg_temp.user_op('append_message',13,'1',49,'{"kind":"comment","text":"assistant"}')$q$,'42501','ai_agent_forbidden','assistant append denied before request/replay');
select throws_ok($q$select pg_temp.user_op('cancel',16,'1',50)$q$,'42501','ai_agent_forbidden','assistant cancel denied');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(5)::text,true);
set local role authenticated;
select is(pg_temp.user_op('append_message',13,'1',49,'{"kind":"comment","text":"second staff"}')->'request'->>'version','2','second staff own append works');
select is(pg_temp.user_op('cancel',16,'1',50)->>'status','cancelled','second staff own cancel works');
select throws_ok($q$select pg_temp.user_op('append_message',11,'2',51,'{"kind":"comment","text":"other"}')$q$,'P0002','ai_agent_not_found','second staff other append denied');
select throws_ok($q$select pg_temp.user_op('cancel',12,'2',52)$q$,'P0002','ai_agent_not_found','second staff other cancel denied');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select is(pg_temp.user_op('append_message',11,'2',53,'{"kind":"comment","text":"admin"}')->'request'->>'version','3','admin can append to another requester');
select is(pg_temp.user_op('cancel',12,'2',54)->>'status','cancelled','admin can cancel another requester');
select throws_ok($q$select pg_temp.user_op('cancel',12,'3',55)$q$,'55000','ai_agent_terminal','terminal cancel denied');
select throws_ok($q$select public.ai_agent_user_api_v1('cancel',jsonb_build_object('id',pg_temp.ai_id(13),'idempotencyKey',pg_temp.ai_id(56)))$q$,'22023','ai_agent_precondition_required','missing version is distinct precondition required');
select throws_ok($q$select pg_temp.user_op('cancel',13,'9999999999999999999',57)$q$,'22023','ai_agent_invalid','decimal overflow rejected safely');
reset role;
select throws_ok($q$update dashboard_private.ai_agent_request_messages set message_seq=99 where request_id=pg_temp.ai_id(10)$q$,'55000','ai_agent_immutable','sequence audit cannot be modified');
select throws_ok($q$delete from dashboard_private.ai_agent_request_events where request_id=pg_temp.ai_id(10)$q$,'55000','ai_agent_immutable','request audit cannot be deleted');
insert into dashboard_private.ai_agent_requests(id,requester_id,title,body) values(pg_temp.ai_id(60),pg_temp.ai_id(2),'expiry','synthetic'),(pg_temp.ai_id(61),pg_temp.ai_id(2),'done','synthetic');
set local role service_role;
select lives_ok($q$select public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(60),'version','1','idempotencyKey',pg_temp.ai_id(62),'claimTokenHash',repeat('a',64)))$q$,'expiry fixture claimed');
reset role;
update dashboard_private.ai_agent_request_claims set lease_expires_at=clock_timestamp()-interval '1 minute' where request_id=pg_temp.ai_id(60);
set local role service_role;
select is(public.ai_agent_bot_api_v1(repeat('d',64),'get',jsonb_build_object('id',pg_temp.ai_id(60)))->>'status','processing','GET does not reclaim expired processing');
select is(public.ai_agent_bot_api_v1(repeat('d',64),'activity',jsonb_build_object('id',pg_temp.ai_id(60)))->'claim'->>'leaseState','expired','expired lease is readable without changing state');
select throws_ok($q$select public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(60),'version','1','idempotencyKey',pg_temp.ai_id(62),'claimTokenHash',repeat('a',64)))$q$,'55000','ai_agent_claim_lost','expired lost-response replay denied');
select throws_ok($q$select pg_temp.bot('renew',60,'2',63)$q$,'55000','ai_agent_claim_lost','expired renewal denied');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select is(pg_temp.user_op('resume',60,'2',64,'{"reason":"Reviewed expired claim","confirmed":true}')->>'status','pending','explicit admin resume with no effect works');
reset role;
set local role service_role;
select lives_ok($q$select public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(61),'version','1','idempotencyKey',pg_temp.ai_id(65),'claimTokenHash',repeat('a',64)))$q$,'done fixture claimed');
select is(pg_temp.bot('done',61,'2',66,'{"result":"notification off works"}')->'request'->>'status','done','notification off completion works');
select is(pg_temp.bot('done',61,'2',66,'{"result":"notification off works"}')->'request'->>'status','done','lost done response replays without a new generation or effect');
select throws_ok($q$select pg_temp.bot('progress',61,'3',67,'{"text":"late status write"}')$q$,'55000','ai_agent_terminal','ended generation cannot mutate request');
reset role;
select is((select count(*) from dashboard_private.chat_delivery_outbox where request_id=pg_temp.ai_id(61)),0::bigint,'notification off creates no intent');
select is((select count(*) from dashboard_private.ai_agent_request_events where request_id=pg_temp.ai_id(61) and kind='done'),1::bigint,'ended-operation replay adds zero completion effects');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','dashboard_private') and p.proname like '%ai_agent%' and pg_get_functiondef(p.oid) ~ 'errcode[[:space:]]*=[[:space:]]*''40001'''),'final AI definitions reserve 40001 for actual database collisions');
-- Real business registry remains empty. This fixture capability is rolled back
-- and checks an exact requester, target and canonical payload hash.
select is((select count(*) from dashboard_private.ai_agent_action_registry),0::bigint,'production domain registry starts empty');
create temp table fixture_acl(allowed boolean);
insert into fixture_acl values(true);
create function pg_temp.fixture_permission(u uuid,t text,h text) returns boolean language sql as $$select u=pg_temp.ai_id(2) and t='fixture/item/1' and h=encode(sha256(convert_to('{"amount": 1}'::jsonb::text,'UTF8')),'hex') and (select allowed from fixture_acl)$$;
insert into dashboard_private.ai_agent_requests(id,requester_id,title,body) values(pg_temp.ai_id(70),pg_temp.ai_id(2),'effect journal','synthetic'),(pg_temp.ai_id(71),pg_temp.ai_id(2),'prepared cancellation','synthetic'),(pg_temp.ai_id(72),pg_temp.ai_id(2),'unknown recovery','synthetic');
create function pg_temp.claim_it(rid integer,kid integer) returns jsonb language sql as $$select public.ai_agent_bot_api_v1(repeat('d',64),'claim',jsonb_build_object('id',pg_temp.ai_id(rid),'version','1','idempotencyKey',pg_temp.ai_id(kid),'claimTokenHash',repeat('a',64)))$$;
create function pg_temp.register_it(rid integer,kid integer) returns jsonb language sql as $$select public.ai_agent_bot_api_v1(repeat('d',64),'register_action',jsonb_build_object('id',pg_temp.ai_id(rid),'claimTokenHash',repeat('a',64),'claimGeneration','1','idempotencyKey',pg_temp.ai_id(kid),'actionKey',pg_temp.ai_id(1000+rid),'stepKey','fixture-step','kind','synthetic_fixture','target','fixture/item/1','payload','{"amount":1}'::jsonb,'payloadHash',encode(sha256(convert_to('{"amount":1}'::jsonb::text,'UTF8')),'hex')))$$;
create function pg_temp.action_it(op text,rid integer,kid integer,aid uuid,rev text,extra jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_bot_api_v1(repeat('d',64),op,jsonb_build_object('id',pg_temp.ai_id(rid),'idempotencyKey',pg_temp.ai_id(kid),'actionId',aid,'revision',rev,'target','fixture/item/1','payloadHash',encode(sha256(convert_to('{"amount":1}'::jsonb::text,'UTF8')),'hex'))||extra)$$;
set local role service_role;
select lives_ok($q$select pg_temp.claim_it(70,80)$q$,'synthetic action request claimed');
select throws_ok($q$select pg_temp.register_it(70,81)$q$,'42501','ai_agent_action_forbidden','lifecycle done grant alone cannot register business action');
reset role;
insert into dashboard_private.ai_agent_action_registry(kind,permission_function,enabled) values('synthetic_fixture','pg_temp.fixture_permission(uuid,text,text)'::regprocedure,true);
set local role service_role;
select throws_ok($q$select pg_temp.register_it(70,81)$q$,'42501','ai_agent_action_forbidden','registered adapter without exact credential domain grant denied');
reset role;
insert into dashboard_private.ai_agent_domain_action_grants(credential_id,kind,target,payload_hash,expires_at) values(pg_temp.ai_id(20),'synthetic_fixture','fixture/item/1',encode(sha256(convert_to('{"amount":1}'::jsonb::text,'UTF8')),'hex'),clock_timestamp()+interval '1 day');
set local role service_role;
insert into ev values('action',pg_temp.register_it(70,81));
select is((select v->>'state' from ev where k='action'),'prepared','prepared registration durably journaled');
select is(jsonb_typeof((select v->'revision' from ev where k='action')),'string','action revision separate precision-safe string');
select is(pg_temp.register_it(70,81),(select v from ev where k='action'),'same action registration replay adds no effect');
select throws_ok($q$select pg_temp.register_it(70,82)$q$,'55000','ai_agent_conflict','different idempotency key cannot duplicate canonical step');
select throws_ok($q$select pg_temp.bot('question',70,'2',83,'{"text":"cannot hide effect"}')$q$,'55000','ai_agent_effect_unresolved','prepared effect blocks question recycling');
select throws_ok($q$select pg_temp.bot('done',70,'2',84,'{"result":"cannot skip effect"}')$q$,'55000','ai_agent_effect_unresolved','prepared effect blocks completion');
select throws_ok($q$select pg_temp.action_it('record_action',70,85,(select (v->>'id')::uuid from ev where k='action'),'1','{"state":"succeeded","evidence":{"resourceName":"fixture/item/1"}}')$q$,'55000','ai_agent_conflict','result without durable start denied');
reset role;
update fixture_acl set allowed=false;
set local role service_role;
select throws_ok($q$select pg_temp.action_it('start_action',70,86,(select (v->>'id')::uuid from ev where k='action'),'1',jsonb_build_object('claimTokenHash',repeat('a',64),'claimGeneration','1'))$q$,'42501','ai_agent_action_forbidden','requester domain permission revalidated immediately before start');
reset role;
update fixture_acl set allowed=true;
update dashboard_private.ai_agent_domain_action_grants set revoked_at=clock_timestamp();
set local role service_role;
select throws_ok($q$select pg_temp.action_it('start_action',70,86,(select (v->>'id')::uuid from ev where k='action'),'1',jsonb_build_object('claimTokenHash',repeat('a',64),'claimGeneration','1'))$q$,'42501','ai_agent_action_forbidden','domain grant revocation prevents start');
reset role;
update dashboard_private.ai_agent_domain_action_grants set revoked_at=null;
set local role service_role;
insert into ev values('started',pg_temp.action_it('start_action',70,86,(select (v->>'id')::uuid from ev where k='action'),'1',jsonb_build_object('claimTokenHash',repeat('a',64),'claimGeneration','1')));
select is((select v->>'state' from ev where k='started'),'started','start event committed before an external operation');
select throws_ok($q$select pg_temp.bot('done',70,'2',87,'{"result":"unresolved"}')$q$,'55000','ai_agent_effect_unresolved','started effect blocks done');
select throws_ok($q$select pg_temp.bot('question',70,'2',88,'{"text":"unresolved"}')$q$,'55000','ai_agent_effect_unresolved','started effect blocks question');
reset role;
update dashboard_private.ai_agent_request_claims set lease_expires_at=clock_timestamp()-interval '1 minute' where request_id=pg_temp.ai_id(70);
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select is(public.ai_agent_user_api_v1('activity',jsonb_build_object('id',pg_temp.ai_id(70)))->'actions'->0->>'state','unknown','expired started effect projects unknown without GET mutation');
select throws_ok($q$select pg_temp.user_op('resume',70,'2',89,'{"reason":"Review unresolved effect","confirmed":true}')$q$,'55000','ai_agent_effect_unresolved','unknown effect blocks explicit resume');
select throws_ok($q$select public.ai_agent_user_api_v1('reconcile_action',jsonb_build_object('reason','Synthetic review','confirmed',true,'id',pg_temp.ai_id(70),'actionId',(select v->>'id' from ev where k='action'),'revision','2','idempotencyKey',pg_temp.ai_id(90),'state','succeeded','evidence','{"confirmed":true}'::jsonb))$q$,'22023','ai_agent_invalid','free confirmed flag is not reconciliation evidence');
select throws_ok($q$select public.ai_agent_user_api_v1('reconcile_action',jsonb_build_object('reason','Synthetic review','confirmed',true,'id',pg_temp.ai_id(70),'actionId',(select v->>'id' from ev where k='action'),'revision','2','idempotencyKey',pg_temp.ai_id(90),'state','succeeded','evidence',jsonb_build_object('type','manual_observation','target','wrong','payloadHash',(select v->>'payloadHash' from ev where k='action'),'resourceName','fixture/item/1','observedAt',clock_timestamp(),'observation','observed')))$q$,'22023','ai_agent_evidence_required','manual observation must bind immutable target/hash');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(2)::text,true);
set local role authenticated;
select is(pg_temp.user_op('cancel',70,'2',91)->>'status','cancelled','request cancellation ends execution');
reset role;
select is((select state from dashboard_private.ai_agent_request_actions where request_id=pg_temp.ai_id(70)),'started','cancellation preserves dispatched evidence');
create function pg_temp.late_snapshot() returns jsonb language sql as $$select jsonb_build_object('ai_agent_requests',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.ai_agent_requests x),'ai_agent_request_claims',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.ai_agent_request_claims x),'ai_agent_request_events',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.ai_agent_request_events x),'ai_agent_request_messages',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.ai_agent_request_messages x),'ai_agent_request_actions',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.ai_agent_request_actions x),'ai_agent_action_events',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.ai_agent_action_events x),'chat_delivery_outbox',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.chat_delivery_outbox x),'chat_delivery_attempts',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.chat_delivery_attempts x),'ai_agent_request_receipts',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.ai_agent_request_receipts x),'chat_send_global_budget',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.chat_send_global_budget x),'chat_space_send_budgets',(select jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text) from dashboard_private.chat_space_send_budgets x),'usage',(select jsonb_build_array(rate_count,rate_window,last_used_at) from dashboard_private.ai_agent_credentials where id=pg_temp.ai_id(20)))$$;
create temp table late_deadlines as
select 'credential'::text k,expires_at from dashboard_private.ai_agent_credentials where id=pg_temp.ai_id(20)
union all select 'queue',expires_at from dashboard_private.ai_agent_credential_grants where credential_id=pg_temp.ai_id(20)
union all select 'domain',expires_at from dashboard_private.ai_agent_domain_action_grants where credential_id=pg_temp.ai_id(20) and kind='synthetic_fixture';
update dashboard_private.ai_agent_credentials set expires_at=clock_timestamp()-interval '1 second' where id=pg_temp.ai_id(20);
update dashboard_private.ai_agent_credential_grants set expires_at=clock_timestamp()-interval '1 second' where credential_id=pg_temp.ai_id(20);
update dashboard_private.ai_agent_domain_action_grants set expires_at=clock_timestamp()-interval '1 second' where credential_id=pg_temp.ai_id(20) and kind='synthetic_fixture';
insert into ev values('late_denial_before',pg_temp.late_snapshot());
set local role service_role;
select throws_ok($q$select pg_temp.action_it('record_action',70,92,(select (v->>'id')::uuid from ev where k='action'),'2','{"state":"succeeded","evidence":{"resourceName":"fixture/item/1"}}')$q$,'28000','ai_agent_unauthorized','credential expiry blocks central late result');
reset role;
select is(pg_temp.late_snapshot(),(select v from ev where k='late_denial_before'),'expired credential leaves all action and dispatch state unchanged');
update dashboard_private.ai_agent_credentials set expires_at=(select expires_at from late_deadlines where k='credential') where id=pg_temp.ai_id(20);
set local role service_role;
insert into ev values('late',pg_temp.action_it('record_action',70,92,(select (v->>'id')::uuid from ev where k='action'),'2','{"state":"succeeded","evidence":{"resourceName":"fixture/item/1"}}'));
select is((select v->>'state' from ev where k='late'),'succeeded','late result can append existing registered action after cancel/expiry');
reset role;
insert into ev values('late_replay_before',pg_temp.late_snapshot());
set local role service_role;
select is(pg_temp.action_it('record_action',70,92,(select (v->>'id')::uuid from ev where k='action'),'2','{"state":"succeeded","evidence":{"resourceName":"fixture/item/1"}}'),(select v from ev where k='late'),'central late-result replay works with expired queue and domain grants');
reset role;
select is(pg_temp.late_snapshot(),(select v from ev where k='late_replay_before'),'late-result replay adds no effects or usage');
update dashboard_private.ai_agent_credential_grants set expires_at=(select expires_at from late_deadlines where k='queue') where credential_id=pg_temp.ai_id(20);
update dashboard_private.ai_agent_domain_action_grants set expires_at=(select expires_at from late_deadlines where k='domain') where credential_id=pg_temp.ai_id(20) and kind='synthetic_fixture';
set local role service_role;
select throws_ok($q$select pg_temp.register_it(70,93)$q$,'55000','ai_agent_terminal','late credential cannot register a new effect');
reset role;
select is((select status from dashboard_private.ai_agent_requests where id=pg_temp.ai_id(70)),'cancelled','late result does not change request');
select is((select count(*) from dashboard_private.ai_agent_action_events where action_id=(select (v->>'id')::uuid from ev where k='action')),3::bigint,'prepared/start/late-result form append-only journal');
select throws_ok($q$update dashboard_private.ai_agent_action_events set kind='changed'$q$,'55000','ai_agent_immutable','effect journal modification denied');
select throws_ok($q$delete from dashboard_private.ai_agent_action_events$q$,'55000','ai_agent_immutable','effect journal deletion denied');
select throws_ok($q$update dashboard_private.ai_agent_request_actions set target='other'$q$,'55000','ai_agent_immutable','action target identity immutable');
set local role service_role;
select is(pg_temp.action_it('record_action',70,105,(select (v->>'id')::uuid from ev where k='action'),'3','{"state":"succeeded","evidence":{"resourceName":"fixture/item/different"}}')->>'state','unknown','same-outcome conflicting late evidence preserved as unresolved incident');
reset role;
select is((select kind from dashboard_private.ai_agent_action_events where action_id=(select (v->>'id')::uuid from ev where k='action') order by seq desc limit 1),'incident','conflicting evidence is appended rather than discarded');
set local role service_role;
select lives_ok($q$select pg_temp.claim_it(71,94)$q$,'prepared cancellation fixture claimed');
insert into ev values('prepared_cancel',pg_temp.register_it(71,95));
select lives_ok($q$select pg_temp.claim_it(72,96)$q$,'reconcile fixture claimed');
insert into ev values('reconcile',pg_temp.register_it(72,97));
select lives_ok($q$select pg_temp.action_it('start_action',72,98,(select (v->>'id')::uuid from ev where k='reconcile'),'1',jsonb_build_object('claimTokenHash',repeat('a',64),'claimGeneration','1'))$q$,'reconcile fixture started');
select is(pg_temp.action_it('record_action',72,99,(select (v->>'id')::uuid from ev where k='reconcile'),'2','{"state":"unknown","evidence":{"observation":"response lost"}}')->>'state','unknown','ambiguous result becomes unknown');
select throws_ok($q$select pg_temp.action_it('start_action',72,100,(select (v->>'id')::uuid from ev where k='reconcile'),'3',jsonb_build_object('claimTokenHash',repeat('a',64),'claimGeneration','1'))$q$,'55000','ai_agent_conflict','unknown has no automatic restart');
