select lives_ok($q$select pg_temp.user_op('cancel',71,'2',101)$q$,'request cancellation cancels prepared action');
select throws_ok($q$select public.ai_agent_user_api_v1('reconcile_action',jsonb_build_object('reason','Synthetic review','confirmed',true,'id',pg_temp.ai_id(72),'actionId',(select v->>'id' from ev where k='reconcile'),'revision','3','idempotencyKey',pg_temp.ai_id(102),'state','succeeded','evidence','{}'::jsonb))$q$,'42501','ai_agent_forbidden','staff answer is not admin reconciliation');
reset role;
select is((select state from dashboard_private.ai_agent_request_actions where request_id=pg_temp.ai_id(71)),'cancelled','only prepared state cancelled');
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select is(public.ai_agent_user_api_v1('reconcile_action',jsonb_build_object('reason','Synthetic review','confirmed',true,'id',pg_temp.ai_id(72),'actionId',(select v->>'id' from ev where k='reconcile'),'revision','3','idempotencyKey',pg_temp.ai_id(103),'state','succeeded','evidence',jsonb_build_object('type','manual_observation','target','fixture/item/1','payloadHash',(select v->>'payloadHash' from ev where k='reconcile'),'resourceName','fixture/item/1','observedAt',clock_timestamp(),'observation','Administrator inspected synthetic persisted result')))->>'state','succeeded','specific admin observation reconciles without implying server verification');
reset role;
select is((select kind from dashboard_private.ai_agent_action_events where action_id=(select (v->>'id')::uuid from ev where k='reconcile') order by seq desc limit 1),'reconciled_manual_observation','manual observation distinctly tagged in append-only audit');
select ok(not has_table_privilege('service_role','dashboard_private.ai_agent_action_registry','INSERT'),'production callers cannot activate registry');
-- A persisted domain receipt is compared by a reviewed server adapter, and its
-- provenance remains distinct from the previous administrator observation.
create temp table fixture_receipts(receipt_id text,target text,payload_hash text,outcome text);
create function pg_temp.fixture_receipt(i text,t text,h text,s text) returns boolean language sql as $$select exists(select 1 from fixture_receipts r where r.receipt_id=i and r.target=t and r.payload_hash=h and r.outcome=s)$$;
update dashboard_private.ai_agent_action_registry set receipt_function='pg_temp.fixture_receipt(text,text,text,text)'::regprocedure where kind='synthetic_fixture';
insert into dashboard_private.ai_agent_requests(id,requester_id,title,body) values(pg_temp.ai_id(74),pg_temp.ai_id(2),'server receipt','synthetic');
set local role service_role;
select lives_ok($q$select pg_temp.claim_it(74,110)$q$,'server receipt fixture claimed');
insert into ev values('receipt_action',pg_temp.register_it(74,111));
select lives_ok($q$select pg_temp.action_it('start_action',74,112,(select (v->>'id')::uuid from ev where k='receipt_action'),'1',jsonb_build_object('claimTokenHash',repeat('a',64),'claimGeneration','1'))$q$,'server receipt action started');
select lives_ok($q$select pg_temp.action_it('record_action',74,113,(select (v->>'id')::uuid from ev where k='receipt_action'),'2','{"state":"unknown","evidence":{}}')$q$,'server receipt fixture unresolved');
reset role;
insert into fixture_receipts select 'persisted-op-1','fixture/item/1',v->>'payloadHash','succeeded' from ev where k='receipt_action';
create function pg_temp.reconcile_receipt(receipt text,kid integer) returns jsonb language sql as $$select public.ai_agent_user_api_v1('reconcile_action',jsonb_build_object('reason','Synthetic review','confirmed',true,'id',pg_temp.ai_id(74),'actionId',(select v->>'id' from ev where k='receipt_action'),'revision','3','idempotencyKey',pg_temp.ai_id(kid),'state','succeeded','evidence',jsonb_build_object('type','domain_receipt','target','fixture/item/1','payloadHash',(select v->>'payloadHash' from ev where k='receipt_action'),'receiptId',receipt)))$$;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select throws_ok($q$select pg_temp.reconcile_receipt('imaginary-op',114)$q$,'22023','ai_agent_evidence_required','server receipt must match actual persisted result');
select throws_ok($q$select public.ai_agent_user_api_v1('reconcile_action',jsonb_build_object('reason','Synthetic review','confirmed',true,'id',pg_temp.ai_id(74),'actionId',(select v->>'id' from ev where k='receipt_action'),'revision','3','idempotencyKey',pg_temp.ai_id(116),'state',null,'evidence','{}'::jsonb))$q$,'22023','ai_agent_invalid','null reconciliation state is input error rather than NOT NULL SQLSTATE');
select is(pg_temp.reconcile_receipt('persisted-op-1',115)->>'state','succeeded','server receipt verifies exact target/hash/outcome');
reset role;
select is((select kind from dashboard_private.ai_agent_action_events where action_id=(select (v->>'id')::uuid from ev where k='receipt_action') order by seq desc limit 1),'reconciled_domain_receipt','server-verified receipt has distinct audit provenance');
-- Real producer values above Number.MAX_SAFE_INTEGER remain decimal strings.
