update dashboard_private.ai_agent_credential_grants set actions=array['read','claim','renew','progress','question','done'] where credential_id=pg_temp.ai_id(20);
-- Following bounded message cursors exposes the newest answer linked to the
-- last question; a resumed request cannot hide it behind the initial page.
insert into dashboard_private.ai_agent_request_messages(id,request_id,message_seq,kind,text,author_kind,author_id) values(pg_temp.ai_id(140),pg_temp.ai_id(75),1,'question','old synthetic question','bot',pg_temp.ai_id(25));
insert into dashboard_private.ai_agent_request_messages(request_id,message_seq,kind,text,author_kind,author_id) select pg_temp.ai_id(75),n,'comment','synthetic history','user',pg_temp.ai_id(3) from generate_series(2,55)n;
insert into dashboard_private.ai_agent_request_messages(request_id,message_seq,kind,text,author_kind,author_id,question_id) values(pg_temp.ai_id(75),56,'answer','newest resumed answer','user',pg_temp.ai_id(3),pg_temp.ai_id(140));
set local role service_role;
insert into ev values('history_page',public.ai_agent_bot_api_v1(repeat('d',64),'activity',jsonb_build_object('id',pg_temp.ai_id(75),'limit',50)));
select is(jsonb_array_length((select v->'messages' from ev where k='history_page')),50,'detail activity pages are bounded');
select is((select v->>'nextMessageSeq' from ev where k='history_page'),'50','detail supplies precision-safe next message cursor');
insert into ev values('history_answer',public.ai_agent_bot_api_v1(repeat('d',64),'activity',jsonb_build_object('id',pg_temp.ai_id(75),'afterMessageSeq',(select v->>'nextMessageSeq' from ev where k='history_page'),'limit',50)));
select is((select v->'messages'->-1->>'questionId' from ev where k='history_answer'),pg_temp.ai_id(140)::text,'resumed newest answer remains discoverable and linked after first page');
select is((select v->>'nextMessageSeq' from ev where k='history_answer'),null,'last bounded page terminates cursor');
reset role;
-- Review-gate regressions first run against FIX_BASE before writers change.
insert into dashboard_private.ai_agent_requests(id,requester_id,title,body,status,version,claim_generation) select pg_temp.ai_id(n),pg_temp.ai_id(3),'review fixture','synthetic','processing',2,1 from generate_series(160,163)n;
insert into dashboard_private.ai_agent_request_claims(request_id,credential_id,token_hash,generation,lease_expires_at) select pg_temp.ai_id(n),pg_temp.ai_id(20),repeat('a',64),1,clock_timestamp()-interval '1 minute' from generate_series(160,163)n;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select throws_ok($q$select pg_temp.user_op('resume',160,'2',164)$q$,'22023','ai_agent_review_required','resume requires separate explicit confirmation and review reason');
select lives_ok($q$select pg_temp.user_op('resume',161,'2',165,'{"reason":"Reviewed expired synthetic run","confirmed":true}')$q$,'confirmed review operation is accepted');
select lives_ok($q$select public.ai_agent_user_api_v1('actions',jsonb_build_object('id',pg_temp.ai_id(75)))$q$,'authorized action list has a full bounded read path');
select lives_ok($q$select public.ai_agent_user_api_v1('action_events',jsonb_build_object('id',pg_temp.ai_id(74),'actionId',(select v->>'id' from ev where k='receipt_action')))$q$,'authorized action journal has a full bounded read path');
select is(public.ai_agent_user_api_v1('activity',jsonb_build_object('id',pg_temp.ai_id(61)))->'notification','null'::jsonb,'consent-off detail exposes safe null notification projection');
reset role;

-- Confirmation and reason are independent review inputs, bound even on replay.
set local role authenticated;
select throws_ok($q$select pg_temp.user_op('resume',162,'2',166,'{"reason":"review","confirmed":false}')$q$,'22023','ai_agent_review_required','false confirmation cannot authorize resume');
select throws_ok($q$select pg_temp.user_op('resume',162,'2',166,'{"reason":"review"}')$q$,'22023','ai_agent_review_required','missing confirmation cannot authorize resume');
select throws_ok($q$select pg_temp.user_op('resume',162,'2',166,'{"reason":"  ","confirmed":true}')$q$,'22023','ai_agent_review_required','blank resume reason is denied');
select throws_ok($q$select pg_temp.user_op('resume',162,'2',166,jsonb_build_object('reason',repeat('x',2001),'confirmed',true))$q$,'22023','ai_agent_review_required','review reason is bounded');
select throws_ok($q$select pg_temp.user_op('resume',161,'2',165,'{"reason":"Changed review reason","confirmed":true}')$q$,'23514','ai_agent_idempotency_conflict','changed resume reason cannot reuse receipt key');
reset role;
select is((select metadata->>'reviewReason' from dashboard_private.ai_agent_request_events where request_id=pg_temp.ai_id(161) and kind='resumed'),'Reviewed expired synthetic run','resume retains review reason in immutable audit');
create function pg_temp.review_reconcile(extra jsonb) returns jsonb language sql as $$select public.ai_agent_user_api_v1('reconcile_action',jsonb_build_object('reason','Synthetic review','confirmed',true,'id',pg_temp.ai_id(74),'actionId',(select v->>'id' from ev where k='receipt_action'),'revision','3','idempotencyKey',pg_temp.ai_id(115),'state','succeeded','evidence',jsonb_build_object('type','domain_receipt','target','fixture/item/1','payloadHash',(select v->>'payloadHash' from ev where k='receipt_action'),'receiptId','persisted-op-1'))||extra)$$;
set local role authenticated;
select throws_ok($q$select pg_temp.review_reconcile('{"confirmed":null}')$q$,'22023','ai_agent_review_required','reconciliation receipt still requires confirmation');
select throws_ok($q$select pg_temp.review_reconcile('{"confirmed":false}')$q$,'22023','ai_agent_review_required','reconciliation rejects false confirmation');
select throws_ok($q$select pg_temp.review_reconcile('{"reason":" "}')$q$,'22023','ai_agent_review_required','reconciliation rejects blank reason');
select throws_ok($q$select pg_temp.review_reconcile('{"reason":"Changed"}')$q$,'23514','ai_agent_idempotency_conflict','changed reconciliation reason conflicts with stored receipt');
select is(pg_temp.review_reconcile('{}')->>'state','succeeded','exact confirmed reconciliation receipt replays');
reset role;
select is((select evidence->>'reviewReason' from dashboard_private.ai_agent_action_events where action_id=(select (v->>'id')::uuid from ev where k='receipt_action') and kind='reconciled_domain_receipt'),'Synthetic review','reconciliation retains review reason in immutable journal');
-- Transaction-local fixtures exercise full traversal without enabling domain writes.
insert into dashboard_private.ai_agent_request_actions(id,request_id,credential_id,action_key,step_key,kind,target,payload,payload_hash,generation,state,created_at)
select pg_temp.ai_id(2000+n),pg_temp.ai_id(75),pg_temp.ai_id(20),pg_temp.ai_id(3000+n),'page-'||n,'synthetic_fixture','fixture/page/'||n,'{}',repeat('a',64),1,'succeeded','2026-10-03 00:00:00+00'::timestamptz from generate_series(1,60)n;
insert into dashboard_private.ai_agent_action_events(action_id,seq,kind,actor_kind,actor_id,evidence)
select pg_temp.ai_id(2001),n,case when n=55 then 'incident' when n=56 then 'reconciled_manual_observation' else 'result' end,'user',pg_temp.ai_id(1),jsonb_build_object('observation',case when n=56 then 'late concrete fixture evidence' else 'synthetic' end,'outcome','succeeded') from generate_series(1,56)n;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(3)::text,true);
set local role authenticated;
insert into ev values('actions_1',public.ai_agent_user_api_v1('actions',jsonb_build_object('id',pg_temp.ai_id(75))));
insert into ev values('actions_2',public.ai_agent_user_api_v1('actions',jsonb_build_object('id',pg_temp.ai_id(75),'cursor',(select v->>'nextCursor' from ev where k='actions_1'))));
select is(jsonb_array_length((select v->'items' from ev where k='actions_1')),50,'action list first page bounded to50');
select is(jsonb_array_length((select v->'items' from ev where k='actions_2')),10,'action continuation reaches all remaining rows');
select is((select count(distinct x->>'id') from ev cross join lateral jsonb_array_elements(v->'items')x where k in('actions_1','actions_2')),60::bigint,'unchanged prior actions do not duplicate or hide later actions');
select is((select v->'nextCursor' from ev where k='actions_2'),'null'::jsonb,'action final page terminates cursor');
select throws_ok($q$select public.ai_agent_user_api_v1('actions',jsonb_build_object('id',pg_temp.ai_id(75),'cursor','bad!'))$q$,'22023','ai_agent_cursor_invalid','malformed action cursor fails closed');
select throws_ok($q$select public.ai_agent_user_api_v1('actions',jsonb_build_object('id',pg_temp.ai_id(75),'limit',10,'cursor',(select v->>'nextCursor' from ev where k='actions_1')))$q$,'22023','ai_agent_cursor_invalid','action cursor is bound to query size');
insert into ev values('journal_1',public.ai_agent_user_api_v1('action_events',jsonb_build_object('id',pg_temp.ai_id(75),'actionId',pg_temp.ai_id(2001))));
insert into ev values('journal_2',public.ai_agent_user_api_v1('action_events',jsonb_build_object('id',pg_temp.ai_id(75),'actionId',pg_temp.ai_id(2001),'cursor',(select v->>'nextCursor' from ev where k='journal_1'))));
select is(jsonb_array_length((select v->'events' from ev where k='journal_1')),50,'journal first page bounded to50');
select is(jsonb_array_length((select v->'events' from ev where k='journal_2')),6,'journal continuation exposes late evidence');
select is((select v->'events'->-2->>'kind' from ev where k='journal_2'),'incident','late incident is discoverable after first50');
select is((select v->'events'->-1->'evidence'->>'observation' from ev where k='journal_2'),'late concrete fixture evidence','late reconciliation evidence is discoverable without mutation');
select is((select count(distinct x->>'seq') from ev cross join lateral jsonb_array_elements(v->'events')x where k in('journal_1','journal_2')),56::bigint,'journal continuation has no gaps or duplicate sequences');
select throws_ok($q$select public.ai_agent_user_api_v1('action_events',jsonb_build_object('id',pg_temp.ai_id(75),'actionId',pg_temp.ai_id(2002),'cursor',(select v->>'nextCursor' from ev where k='journal_1')))$q$,'22023','ai_agent_cursor_invalid','journal cursor bound to action identity');
select throws_ok($q$select public.ai_agent_user_api_v1('action_events',jsonb_build_object('id',pg_temp.ai_id(75),'actionId',(select v->>'id' from ev where k='receipt_action')))$q$,'P0002','ai_agent_not_found','action must belong to authorized request');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
