select throws_ok($q$select public.ai_agent_user_api_v1('actions',jsonb_build_object('id',pg_temp.ai_id(75),'cursor',(select v->>'nextCursor' from ev where k='actions_1')))$q$,'22023','ai_agent_cursor_invalid','action cursor bound to current principal');
